import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Parlaklık, fotoğrafın ne kadar aydınlık göründüğünü belirler. Koyu fotoğrafı açar, parlak fotoğrafı kısar.</p>\n<p>Doğru parlaklık, fotoğrafı kurtarır. Yanlış parlaklık ise görseli yıkar ve renkleri soldurur.</p>\n<p>Bu kılavuz, parlaklık kaydırıcısının nasıl çalıştığını, hızlı ön ayarları ve koyu fotoğrafları düzeltmenin yollarını anlatıyor.</p>\n<h2 id=\"what-brightness-does\">Parlaklık gerçekte ne yapar?</h2>\n<p>Parlaklık, tüm pikselleri birlikte aydınlatır ya da karartır. Koyu ve açık alanlar birlikte değişir.</p>\n<p>Parlaklık artırmak, gölgeleri açar. Parlaklık azaltmak, parlak alanları kısar.</p>\n<p>Parlaklık, kontrastı değiştirmez. Yalnızca genel aydınlık seviyesini kaydırır.</p>\n<h2 id=\"why-photos-are-dark\">Fotoğraflar neden koyu çıkar?</h2>\n<p>Az ışık, koyu fotoğrafın başlıca nedenidir. İç mekân ve gece çekimleri genellikle koyu olur.</p>\n<p>Kamera, parlak arka plana göre ölçüm yaparsa konu koyu kalır. Pencere önünde çekilen portre buna örnektir.</p>\n<p>Eski taramalar da koyu olabilir. Zamanla solan fotoğraflar, taramada koyu çıkar.</p>\n<h2 id=\"brightening-vs-exposure\">Aydınlatma ve pozlama: aynı şey mi?</h2>\n<p>Benzer ama aynı değildir. Pozlama, çekim sırasındaki ışık miktarıdır; parlaklık, sonradan yapılan ayarlamadır.</p>\n<p>Parlaklık, tüm tonları eşit kaydırır. Pozlama düzeltmesi, parlak alanları koruyarak gölgeleri açar.</p>\n<p>Pratikte ikisi de fotoğrafı açar. Düzenlemede parlaklık kaydırıcısı yeterlidir.</p>\n<h2 id=\"slider-explained\">Parlaklık kaydırıcısı, açıklanıyor</h2>\n<p>Kaydırıcı, -100 ile +100 arasında çalışır. Sıfır, orijinal fotoğraftır.</p>\n<p>Araçta parlaklığı küçük adımlarla ayarlayın; koyu fotoğrafların çoğu +10 ile +20 arasında düzelir.</p>\n<p>Araçta +50'nin üstüne çıkmayın; aşırı parlaklık, renkleri soldurur ve karede gürültü oluşturur.</p>\n<h2 id=\"quick-presets\">Tek tıkla düzeltmeler için hızlı ön ayarlar</h2>\n<p>Araçtaki hızlı ön ayarlarla başlayın; hafif aç, orta aç ve koyulaştır hazır seçenekler arasındadır.</p>\n<p>Ön ayarı seçtikten sonra kaydırıcıyla ince ayar yapın. Ön ayar, başlangıç noktasıdır.</p>\n<p>Kendi ön ayarınızı kaydedin. Aynı düzeltmeyi sürekli yapıyorsanız zaman kazanırsınız.</p>\n<h2 id=\"compare-modes\">Karşılaştırma modları: önce, sonra ve bölünmüş</h2>\n<p>Karşılaştırma modu, orijinali ve düzenlenen sürümü yan yana gösterir. Farkı anında görürsünüz.</p>\n<p>Bölünmüş görünüm, fotoğrafın yarısını orijinal gösterir. Kaydırıcıyı hareket ettirerek karşılaştırın.</p>\n<p>Karşılaştırma, aşırı düzenlemeyi önler. Farkı gördükçe ayarı durdurursunuz.</p>\n<h2 id=\"brightening-portraits\">Portreleri aydınlatmak</h2>\n<p>Portrelerde yüzü aydınlatın. Yüz, fotoğrafın en önemli parçasıdır.</p>\n<p>Parlaklığı +10 ile +20 arasında tutun. Fazla parlaklık, cildi soldurur.</p>\n<p>Gözleri kontrol edin. Gözler, portrenin odak noktasıdır; karanlık kalmamalıdır.</p>\n<h2 id=\"brightening-landscapes\">Manzaraları aydınlatmak</h2>\n<p>Manzaralarda ön planı aydınlatın. Gökyüzü zaten parlaktır; ön plan karanlık kalır.</p>\n<p>Parlaklığı +10 ile +15 arasında tutun. Fazla parlaklık, gökyüzünü beyazlatır.</p>\n<p>Ufuk çizgisini kontrol edin. Aydınlatma, gökyüzü ile yer arasındaki dengeyi bozmamalıdır.</p>\n<h2 id=\"brightening-screenshots\">Ekran görüntüleri ve belgeleri aydınlatmak</h2>\n<p>Araçta koyu ekran görüntülerinin parlaklığını yükseltin; böylece yazılar okunabilir olur.</p>\n<p>Belgelerde +15 ile +25 arası kullanın. Kâğıt beyazı açılmalı, yazı koyu kalmalıdır.</p>\n<p>Belgeyi aydınlattıktan sonra kontrastı kontrol edin. Yazılar, zeminden ayrılmalıdır.</p>\n<h2 id=\"darkening-photos\">Aydınlatmak yerine koyulaştırmak</h2>\n<p>Çok parlak fotoğrafları koyulaştırın. Parlaklık azaltmak, patlayan alanları kurtarır.</p>\n<p>Metin için arka planı koyulaştırın. Beyaz yazı, koyu zeminde okunur.</p>\n<p>Araçta koyulaştırma, renkleri doygunlaştırır; soluk bir fotoğraf, koyulaştıkça canlılaşır.</p>\n<h2 id=\"noise-and-quality\">Gürültü, kalite ve aydınlatmanın sınırları</h2>\n<p>Aşırı aydınlatma, gürültü çıkarır. Koyu alanlardaki gren, aydınlatınca belirginleşir.</p>\n<p>Çok koyu fotoğraf kurtarılamaz. Kaybolan ayrıntı, parlaklıkla geri gelmez.</p>\n<p>Sınırı bilin. +30'un üzeri, çoğu fotoğrafta gürültü demektir.</p>\n<h2 id=\"formats-and-export\">Formatlar ve dışa aktarma</h2>\n<p>Düzenlenen fotoğraflar için JPG kullanın. Hafif dosyalar paylaşımı hızlandırır.</p>\n<p>Saydam görselleri PNG olarak kaydedin. JPG, saydam alanları beyazlatır.</p>\n<p>Dışa aktarmadan önce önizlemeyi kontrol edin. Parlaklık ve kontrast doğru olmalıdır.</p>\n<h2 id=\"brightness-and-contrast\">Parlaklık ve kontrast birlikte çalışır</h2>\n<p>Parlaklık açar, kontrast derinlik verir. İkisi birlikte kullanıldığında fotoğraf canlanır.</p>\n<p>Önce parlaklığı, sonra kontrastı ayarlayın. Sıralama, doğru dengeyi bulmanızı sağlar.</p>\n<p>İkisini birlikte abartmayın. Aşırı parlaklık ve kontrast, fotoğrafı yapay gösterir.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden düzenlemek</h2>\n<p>Parlaklık aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Özel fotoğraflar için bu önemlidir. Aile ve müşteri görsellerini güvenle aydınlatabilirsiniz.</p>\n<p>Sekme kapanınca veriler silinir. Fotoğraflarınız yalnızca cihazınızda kalır.</p>\n<h2 id=\"common-mistakes\">Parlaklık ayarlarken yaygın hatalar</h2>\n<p>En yaygın hata, aşırı aydınlatmaktır. +50'nin üzeri, renkleri soldurur.</p>\n<p>Bir başka hata, karşılaştırmadan düzenlemektir. Orijinali görmeden ayar yapmak, aşırıya kaçar.</p>\n<p>Üçüncü hata, orijinali silmektir. Düzenlenen fotoğraf ayrı bir dosyadır; orijinali saklayın.</p>\n<h2 id=\"brightness-workflow\">Temiz parlaklık düzenlemeleri için bir akış</h2>\n<p>Önce fotoğrafın ne kadar koyu olduğunu değerlendirin. Hafif koyuysa +10, çok koyuysa +20 kullanın.</p>\n<p>Sonra kaydırıcıyla ayarlayın. Karşılaştırma moduyla farkı izleyin.</p>\n<p>Son olarak kontrastı kontrol edin. Parlaklık tek başına yeterli olmayabilir.</p>\n<h2 id=\"brightening-for-social\">Sosyal medya için fotoğraf aydınlatmak</h2>\n<p>Sosyal medyada fotoğraflar parlak görünmelidir. Hafif aydınlatma, akışta dikkat çeker.</p>\n<p>Parlaklığı +10 ile +15 arasında tutun. Fazla parlaklık, yapay görünür.</p>\n<p>Tüm gönderilerde aynı ayarı kullanın. Tutarlılık, profilinizi tanınır kılar.</p>\n<p>Özetle: az aydınlatın, karşılaştırın, kontrastı unutmayın. Adımlar için <a href=\"/tr/blog/gorsel-parlakligi-nasil-ayarlanir\">Görsel parlaklığı nasıl ayarlanır</a> yazısına bakın; karşılaştırma için <a href=\"/tr/blog/parlaklik-vs-pozlama-vs-kontrast\">parlaklık, pozlama ve kontrast karşılaştırması</a> yardımcı olur. Kontrast için <a href=\"/tr/gorsel-kontrast-ayarla\">görsel kontrast düzenleyici</a> hazırdır; araç ise <a href=\"/tr/gorsel-parlaklik-ayarla\">görsel parlaklık düzenleyici</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Koyu bir fotoğrafı ne kadar aydınlatmalıyım?","answer":"Genellikle +10 ile +20 arası yeterlidir. Küçük adımlarla ayarlayın ve karşılaştırma moduyla farkı izleyin. +30'un üzeri çoğu fotoğrafta gürültü çıkarır ve renkleri soldurur."},{"question":"Fotoğrafım aydınlattıktan sonra neden soluk görünüyor?","answer":"Çünkü aşırı parlaklık renkleri soldurur ve kontrastı düşürür. Parlaklığı azaltın ve biraz kontrast ekleyin. Önce parlaklığı, sonra kontrastı ayarlayın; ikisi birlikte fotoğrafı canlandırır."},{"question":"Çok az ışıkla çekilen bir fotoğrafı aydınlatmak düzeltebilir mi?","answer":"Kısmen. Hafif koyu fotoğraflar kurtarılır; çok koyu fotoğraflarda kaybolan ayrıntı geri gelmez. Aşırı aydınlatma gürültü çıkarır. Sınırı bilin; +30'un üzeri genellikle işe yaramaz."},{"question":"Fotoğrafı kırpmadan önce mi sonra mı aydınlatmalıyım?","answer":"Önce kırpın, sonra aydınlatın. Kırpma, atılan pikselleri çıkarır; aydınlatma yalnızca kalan pikselleri işler. Sıralama: önce kırpın, sonra parlaklığı ayarlayın, en son kontrastı kontrol edin."},{"question":"Görsel aydınlatmak dosya boyutunu değiştirir mi?","answer":"Çok az. Parlaklık, piksel değerlerini değiştirir ama dosya boyutunu neredeyse hiç etkilemez. Boyut, format ve kalite ayarına bağlıdır; parlaklık boyutu değiştirmez."},{"question":"Kişisel bir fotoğrafı tarayıcı aracında aydınlatmak güvenli mi?","answer":"Evet. Araç tamamen tarayıcıda çalışır; fotoğraflarınız sunucuya yüklenmez. İş bitince tarayıcı verisi silinir. Özel fotoğrafları güvenle düzenleyebilirsiniz."}];
